// P4Font - bitmap font format used by P4Panel32::setFont().
// Fonts are generated by extras/fontgen/make_vn_font.py (e.g. DejaVuVN_9.h, DejaVuVN_12.h, DejaVuVN_16.h).
#ifndef P4FONT_H
#define P4FONT_H
#include <stdint.h>

struct P4Glyph {
  uint16_t offset;   // byte offset of the glyph bitmap in P4Font::bitmap
  uint8_t  w, h;     // bitmap size in pixels (1 bit per pixel, row by row, MSB first)
  int8_t   dx, dy;   // top-left of the bitmap relative to the pen position on the baseline (dy < 0 = above)
  uint8_t  adv;      // horizontal advance in pixels
};

struct P4Font {
  const uint8_t*  bitmap;
  const P4Glyph*  glyphs;     // parallel to codes[]
  const uint16_t* codes;      // Unicode code points, sorted ascending
  uint16_t        count;
  uint8_t         ascent;     // pixels from the top of the line cell to the baseline
  uint8_t         height;     // line cell height (ascent + descent) in pixels
};

// Glyph lookup by Unicode code point (binary search); NULL if the font has no such glyph.
static inline const P4Glyph* P4FontFind(const P4Font* f, uint32_t cp) {
  int lo = 0, hi = (int)f->count - 1;
  while (lo <= hi) {
    int mid = (lo + hi) >> 1;
    uint32_t c = f->codes[mid];
    if (c == cp) return &f->glyphs[mid];
    if (c < cp) lo = mid + 1; else hi = mid - 1;
  }
  return 0;
}
#endif
